  "p.hammock.heading": "汇总任务：横跨其他任务的摘要任务",
  "p.hammock.says":
    "汇总任务是一种摘要，其日期来自它所链接的本计划任务，从最早开始到最晚完成。它不在依赖网络中，因此从不改变任何任务的浮动时间或完成日期。只有当任务没有工期、工作量、约束或依赖时才能成为汇总任务，其计划开始日期会被清除；将其改回任务会删除它的所有链接。汇总任务链接本计划的任务或另一个汇总任务，不能链接自身，不能重复，也不能形成循环。",
